Fixes: d112a8163f83 ("gma500/cdv: Add eDP support")

Signed-off-by: Tom Rix <trix@redhat.com>
Signed-off-by: Patrik Jakobsson <patrik.r.jakobsson@gmail.com>
Link: https://patchwork.freedesktop.org/patch/msgid/20200805205911.20927-1-trix@redhat.com

Here is the root cause:
The bug was caused by an inadequate error check in the `cdv_intel_dp_init` function, where the condition only checked for a return value of zero from the `cdv_intel_dp_aux_native_read()` function. This did not account for other failure scenarios, as the function can return positive values on success and any non-positive value indicates a failure. As a result, the code could incorrectly assume a successful read when it was not, leading to potential issues in eDP initialization.

Here is the patch:

 void
 cdv_intel_dp_init(struct drm_device *dev, struct psb_intel_mode_device *mode_dev, int output_reg)
 {
 	struct gma_encoder *gma_encoder;
 	struct gma_connector *gma_connector;
 	struct drm_connector *connector;
 	struct drm_encoder *encoder;
 	struct cdv_intel_dp *intel_dp;
 	const char *name = NULL;
 	int type = DRM_MODE_CONNECTOR_DisplayPort;

 	gma_encoder = kzalloc(sizeof(struct gma_encoder), GFP_KERNEL);
 	if (!gma_encoder)
 		return;
         gma_connector = kzalloc(sizeof(struct gma_connector), GFP_KERNEL);
         if (!gma_connector)
                 goto err_connector;
 	intel_dp = kzalloc(sizeof(struct cdv_intel_dp), GFP_KERNEL);
 	if (!intel_dp)
 	        goto err_priv;

 	if ((output_reg == DP_C) && cdv_intel_dpc_is_edp(dev))
 		type = DRM_MODE_CONNECTOR_eDP;

 	connector = &gma_connector->base;
 	encoder = &gma_encoder->base;

 	drm_connector_init(dev, connector, &cdv_intel_dp_connector_funcs, type);
 	drm_simple_encoder_init(dev, encoder, DRM_MODE_ENCODER_TMDS);

 	gma_connector_attach_encoder(gma_connector, gma_encoder);

 	if (type == DRM_MODE_CONNECTOR_DisplayPort)
 		gma_encoder->type = INTEL_OUTPUT_DISPLAYPORT;
         else
 		gma_encoder->type = INTEL_OUTPUT_EDP;


 	gma_encoder->dev_priv=intel_dp;
 	intel_dp->encoder = gma_encoder;
 	intel_dp->output_reg = output_reg;

 	drm_encoder_helper_add(encoder, &cdv_intel_dp_helper_funcs);
 	drm_connector_helper_add(connector, &cdv_intel_dp_connector_helper_funcs);

 	connector->polled = DRM_CONNECTOR_POLL_HPD;
 	connector->interlace_allowed = false;
 	connector->doublescan_allowed = false;

 	drm_connector_register(connector);

 	/* Set up the DDC bus. */
 	switch (output_reg) {
 		case DP_B:
 			name = "DPDDC-B";
 			gma_encoder->ddi_select = (DP_MASK | DDI0_SELECT);
 			break;
 		case DP_C:
 			name = "DPDDC-C";
 			gma_encoder->ddi_select = (DP_MASK | DDI1_SELECT);
 			break;
 	}

 	cdv_disable_intel_clock_gating(dev);

 	cdv_intel_dp_i2c_init(gma_connector, gma_encoder, name);
         /* FIXME:fail check */
 	cdv_intel_dp_add_properties(connector);

 	if (is_edp(gma_encoder)) {
 		int ret;
 		struct edp_power_seq cur;
                 u32 pp_on, pp_off, pp_div;
 		u32 pwm_ctrl;

 		pp_on = REG_READ(PP_CONTROL);
 		pp_on &= ~PANEL_UNLOCK_MASK;
 	        pp_on |= PANEL_UNLOCK_REGS;

 		REG_WRITE(PP_CONTROL, pp_on);

 		pwm_ctrl = REG_READ(BLC_PWM_CTL2);
 		pwm_ctrl |= PWM_PIPE_B;
 		REG_WRITE(BLC_PWM_CTL2, pwm_ctrl);

                 pp_on = REG_READ(PP_ON_DELAYS);
                 pp_off = REG_READ(PP_OFF_DELAYS);
                 pp_div = REG_READ(PP_DIVISOR);

 		/* Pull timing values out of registers */
                 cur.t1_t3 = (pp_on & PANEL_POWER_UP_DELAY_MASK) >>
                         PANEL_POWER_UP_DELAY_SHIFT;

                 cur.t8 = (pp_on & PANEL_LIGHT_ON_DELAY_MASK) >>
                         PANEL_LIGHT_ON_DELAY_SHIFT;

                 cur.t9 = (pp_off & PANEL_LIGHT_OFF_DELAY_MASK) >>
                         PANEL_LIGHT_OFF_DELAY_SHIFT;

                 cur.t10 = (pp_off & PANEL_POWER_DOWN_DELAY_MASK) >>
                         PANEL_POWER_DOWN_DELAY_SHIFT;

                 cur.t11_t12 = ((pp_div & PANEL_POWER_CYCLE_DELAY_MASK) >>
                                PANEL_POWER_CYCLE_DELAY_SHIFT);

                 DRM_DEBUG_KMS("cur t1_t3 %d t8 %d t9 %d t10 %d t11_t12 %d\n",
                               cur.t1_t3, cur.t8, cur.t9, cur.t10, cur.t11_t12);


 		intel_dp->panel_power_up_delay = cur.t1_t3 / 10;
                 intel_dp->backlight_on_delay = cur.t8 / 10;
                 intel_dp->backlight_off_delay = cur.t9 / 10;
                 intel_dp->panel_power_down_delay = cur.t10 / 10;
                 intel_dp->panel_power_cycle_delay = (cur.t11_t12 - 1) * 100;

                 DRM_DEBUG_KMS("panel power up delay %d, power down delay %d, power cycle delay %d\n",
                               intel_dp->panel_power_up_delay, intel_dp->panel_power_down_delay,
                               intel_dp->panel_power_cycle_delay);

                 DRM_DEBUG_KMS("backlight on delay %d, off delay %d\n",
                               intel_dp->backlight_on_delay, intel_dp->backlight_off_delay);


 		cdv_intel_edp_panel_vdd_on(gma_encoder);
 		ret = cdv_intel_dp_aux_native_read(gma_encoder, DP_DPCD_REV,
 					       intel_dp->dpcd,
 					       sizeof(intel_dp->dpcd));
 		cdv_intel_edp_panel_vdd_off(gma_encoder);
-		if (ret == 0) {
+		if (ret <= 0) {
 			/* if this fails, presume the device is a ghost */
 			DRM_INFO("failed to retrieve link info, disabling eDP\n");
 			drm_encoder_cleanup(encoder);
 			cdv_intel_dp_destroy(connector);
 			goto err_priv;
 		} else {
         		DRM_DEBUG_KMS("DPCD: Rev=%x LN_Rate=%x LN_CNT=%x LN_DOWNSP=%x\n",
 				intel_dp->dpcd[0], intel_dp->dpcd[1], 
 				intel_dp->dpcd[2], intel_dp->dpcd[3]);

 		}
 		/* The CDV reference driver moves pnale backlight setup into the displays that
 		   have a backlight: this is a good idea and one we should probably adopt, however
 		   we need to migrate all the drivers before we can do that */
                 /*cdv_intel_panel_setup_backlight(dev); */
 	}
 	return;

 err_priv:
 	kfree(gma_connector);
 err_connector:
 	kfree(gma_encoder);
 }
-- 


